#include "appearance.h"

#include <cstring>
#include <unordered_map>
#include <vector>

#include "../util/strings.h"

namespace nav::appearance {
namespace {

// What each head and body looks like, in feature words: written for the mod from the game's
// previews (appearance_data.h is generated by tools/appearance_table.py from those notes). Keyed
// by the mesh without its skin tone ("c036malgt_dave" -> "c036ma_dave"): the same head or body
// comes in the light, medium and dark skins.
struct Entry {
    const char* key;
    std::vector<Str> words;
};
#include "appearance_data.h"

// "c036malgt_dave" -> "c036ma_dave", "b002mafitlgt_casual" -> "b002mafit_casual".
std::string KeyOf(const std::string& mesh) {
    size_t underscore = mesh.find('_');
    std::string prefix = mesh.substr(0, underscore), rest = underscore == std::string::npos ? "" : mesh.substr(underscore);
    for (const char* skin : {"lgt", "med", "drk"}) {
        size_t at = prefix.find(skin);
        if (at != std::string::npos) {
            prefix.erase(at, std::strlen(skin));
            break;
        }
    }
    std::string key = prefix + rest;
    for (char& c : key) c = (char)tolower((unsigned char)c);
    return key;
}

const std::unordered_map<std::string, const std::vector<Str>*>& Table() {
    static std::unordered_map<std::string, const std::vector<Str>*> table = [] {
        std::unordered_map<std::string, const std::vector<Str>*> t;
        for (const Entry& e : kEntries) t.emplace(e.key, &e.words);
        return t;
    }();
    return table;
}

}  // namespace

std::string Describe(const std::string& mesh) {
    auto it = Table().find(KeyOf(mesh));
    if (it == Table().end()) return "";
    std::string s;
    for (Str w : *it->second) s += (s.empty() ? "" : ", ") + std::string(S(w));
    return s;
}

}  // namespace nav::appearance
